SELECT ID_CLIENTE, SUM(VALOR) AS TOTAL FROM VENDAS ORDER BY SUM(VALOR) DESC;
SELECT ID_CLIENTE, SUM(VALOR) AS TOTAL, RANK() OVER (ORDER BY SUM(VALOR) DESC) AS POSICAO FROM VENDAS GROUP BY ID_CLIENTE ORDER BY TOTAL DESC;
SELECT ID_CLIENTE, RANK() OVER (ORDER BY SUM(VALOR) DESC) AS POSICAO FROM VENDAS ORDER BY POSICAO;
